def parse_amount(value:str)->int:
    return int(value)

import csv

totals = {}
accepted = 0
with open('input.csv', newline='') as source:
    for row in csv.DictReader(source):
        amount = parse_amount(row['amount'])
        if amount >= 0:
            kind = row['kind']
            totals[kind] = totals.get(kind, 0) + amount
            accepted += 1
with open('report.csv', 'w', newline='') as target:
    writer = csv.writer(target, lineterminator='\n')
    writer.writerow(['kind', 'total'])
    for kind in sorted(totals):
        writer.writerow([kind, totals[kind]])
print(accepted)

def words_from_line(line:str)->list:
    return line.lower().split()

counts = {}
total = 0
with open('input.txt') as source:
    for line in source:
        for word in words_from_line(line):
            counts[word] = counts.get(word, 0) + 1
            total += 1
with open('report.txt', 'w', newline='') as target:
    for word in sorted(counts):
        target.write(word + '=' + str(counts[word]) + '\n')
print(total)

def normalize(value):
    return value.strip().lower().replace('café','coffee')
def count_words(value):
    return len(value.split())
def render(value, count):
    return value.upper()+'\t'+str(count)+'\n'
rows = 0
with open('input.txt') as source:
    with open('report.txt','w',newline='') as target:
        for line in source:
            normalized = normalize(line)
            target.write(render(normalized, count_words(normalized)))
            rows += 1
print(rows)
